// Des: List likely JSON or page URLs behind a JavaScript shell
// Flo: link tags > wp-json > Next buildId > Nuxt payload > SvelteKit data > /api/ strings > openapi > iframes > .json twin > same-host dedupe
// I/O: page URL + HTML text (caller) > Cand list (absolute same-host URLs, kind label, page flag)
// ===================================================================
const std = @import("std"); const mem = std.mem; const urln = @import("ut-urlz-norm.zig"); const stru = @import("pa-stru-data.zig");
const CF = .{ .maxc = 32, .scrn = 12, .ulen = 200, .jtyp = @as([]const []const u8, &.{ "application/json", "application/feed+json", "application/vnd.api+json" }) };
pub const Cand = struct { urlz: []const u8, kind: []const u8, page: bool = false };
fn attrGet(tagz: []const u8, name: []const u8) ?[]const u8 { var buf: [16]u8 = undefined; const pat = std.fmt.bufPrint(&buf, "{s}=", .{name}) catch return null; var from: usize = 0; while (std.ascii.findIgnoreCasePos(tagz, from, pat)) |hit| { from = hit + pat.len; if (hit == 0 or !std.ascii.isWhitespace(tagz[hit - 1])) continue; if (from >= tagz.len) return null; const quot = tagz[from]; if (quot != '"' and quot != '\'') return null; const endz = mem.findScalarPos(u8, tagz, from + 1, quot) orelse return null; return tagz[from + 1 .. endz]; } return null; }
pub fn origin(aren: std.mem.Allocator, part: urln.Part) ![]const u8 { if (part.dflt) return std.fmt.allocPrint(aren, "{s}://{s}", .{ part.sche, part.host }); return std.fmt.allocPrint(aren, "{s}://{s}:{d}", .{ part.sche, part.host, part.port }); }
pub fn joinz(aren: std.mem.Allocator, part: urln.Part, orig: []const u8, refz: []const u8) !?[]const u8 { const ref = mem.trim(u8, refz, " \t\r\n"); if (ref.len == 0 or ref.len > CF.ulen or ref[0] == '#') return null; if (std.ascii.startsWithIgnoreCase(ref, "http://") or std.ascii.startsWithIgnoreCase(ref, "https://")) return try aren.dupe(u8, ref); if (std.ascii.startsWithIgnoreCase(ref, "javascript:") or std.ascii.startsWithIgnoreCase(ref, "data:")) return null; if (mem.startsWith(u8, ref, "//")) return try std.fmt.allocPrint(aren, "{s}:{s}", .{ part.sche, ref }); if (ref[0] == '/') return try std.fmt.allocPrint(aren, "{s}{s}", .{ orig, ref }); const dirx = if (mem.findScalarLast(u8, part.path, '/')) |sl| part.path[0 .. sl + 1] else "/"; return try std.fmt.allocPrint(aren, "{s}{s}{s}", .{ orig, dirx, ref }); }
fn sameHost(part: urln.Part, urlz: []const u8) bool { const other = urln.urlSplit(urlz) catch return false; return std.ascii.eqlIgnoreCase(other.host, part.host) and other.port == part.port; }
const Bild = struct { aren: std.mem.Allocator, part: urln.Part, orig: []const u8, list: std.ArrayList(Cand) = .empty,
fn add(self: *Bild, refz: []const u8, kind: []const u8, page: bool) !void { if (self.list.items.len >= CF.maxc) return; const urlz = (try joinz(self.aren, self.part, self.orig, refz)) orelse return; if (!sameHost(self.part, urlz)) return; for (self.list.items) |item| if (mem.eql(u8, item.urlz, urlz)) return; try self.list.append(self.aren, .{ .urlz = urlz, .kind = kind, .page = page }); } };
fn pathTrim(part: urln.Part) []const u8 { return mem.trimEnd(u8, part.path, "/"); }
fn tagsOf(bld: *Bild, page: []const u8, open: []const u8) !void { var indx: usize = 0; var cnt: usize = 0; while (std.ascii.findIgnoreCasePos(page, indx, open)) |beg| { const endz = mem.findScalarPos(u8, page, beg, '>') orelse break; indx = endz + 1; cnt += 1; if (cnt > 64) break; const tagz = page[beg..endz]; if (std.ascii.eqlIgnoreCase(open, "<iframe")) { if (attrGet(tagz, "src")) |src| try bld.add(src, "ifrm", true); continue; } const href = attrGet(tagz, "href") orelse continue; const rel = attrGet(tagz, "rel") orelse ""; if (std.ascii.findIgnoreCase(rel, "api.w.org") != null) { const root = if (mem.endsWith(u8, href, "/")) href else try std.fmt.allocPrint(bld.aren, "{s}/", .{href}); try bld.add(try std.fmt.allocPrint(bld.aren, "{s}wp/v2/posts?per_page=10", .{root}), "wpjs", false); try bld.add(try std.fmt.allocPrint(bld.aren, "{s}wp/v2/pages?per_page=10", .{root}), "wpjs", false); continue; } if (std.ascii.findIgnoreCase(rel, "alternate") == null) continue; const typz = attrGet(tagz, "type") orelse continue; for (CF.jtyp) |jt| if (std.ascii.findIgnoreCase(typz, jt) != null) { try bld.add(href, "link", false); break; }; } }
fn nextBild(bld: *Bild, page: []const u8) !void { const blks = try stru.blokFind(bld.aren, page); for (blks) |blk| { if (blk.kind != .next) continue; const valu = std.json.parseFromSliceLeaky(std.json.Value, bld.aren, blk.json, .{}) catch continue; if (valu != .object) continue; const bid = valu.object.get("buildId") orelse continue; if (bid != .string or bid.string.len == 0 or bid.string.len > 64) continue; const tail = mem.trim(u8, bld.part.path, "/"); try bld.add(try std.fmt.allocPrint(bld.aren, "/_next/data/{s}/{s}.json", .{ bid.string, if (tail.len == 0) "index" else tail }), "next", false); return; } }
fn scrStrs(bld: *Bild, page: []const u8) !void { var cnt: usize = 0; for ([_][]const u8{ "/api/", "/wp-json/" }) |pat| { var indx: usize = 0; while (mem.findPos(u8, page, indx, pat)) |hit| { indx = hit + pat.len; if (hit == 0 or (page[hit - 1] != '"' and page[hit - 1] != '\'')) continue; var endz = hit; while (endz < page.len and endz - hit < CF.ulen and page[endz] != '"' and page[endz] != '\'' and page[endz] != '<' and page[endz] != '`' and !std.ascii.isWhitespace(page[endz])) : (endz += 1) {} const cand = page[hit..endz]; if (mem.findAny(u8, cand, "{}$\\") != null or endz >= page.len) continue; try bld.add(cand, "scri", false); cnt += 1; if (cnt >= CF.scrn) return; } } }
pub fn apizFind(aren: std.mem.Allocator, norm: []const u8, page: []const u8) ![]Cand { const part = try urln.urlSplit(norm); var bld: Bild = .{ .aren = aren, .part = part, .orig = try origin(aren, part) }; try tagsOf(&bld, page, "<link"); try nextBild(&bld, page); if (std.ascii.findIgnoreCase(page, "__NUXT_DATA__") != null) try bld.add(try std.fmt.allocPrint(aren, "{s}/_payload.json", .{pathTrim(part)}), "nuxt", false); if (std.ascii.findIgnoreCase(page, "sveltekit") != null) try bld.add(try std.fmt.allocPrint(aren, "{s}/__data.json", .{pathTrim(part)}), "svel", false); try scrStrs(&bld, page); if (std.ascii.findIgnoreCase(page, "swagger") != null or std.ascii.findIgnoreCase(page, "openapi") != null) { try bld.add("/openapi.json", "oapi", false); try bld.add("/swagger.json", "oapi", false); } try tagsOf(&bld, page, "<iframe"); const trim = pathTrim(part); if (trim.len > 0 and !mem.endsWith(u8, trim, ".json")) try bld.add(try std.fmt.allocPrint(aren, "{s}.json", .{trim}), "twin", false); return bld.list.toOwnedSlice(aren); }
